// Cloudflare Pages Function -- /api/project-override
// PER-SECTION MANUAL OVERRIDES for a project record (the office project-record
// view). Every project record renders 11 collapsible "schema cards" (General
// Info, PF Team, Contract Info, Engineering & Design, Project Safety, Site
// Readiness, Equipment, Material, QA/QC, Financials, Project Closeout). The base
// values come from STATIC synced JS (data/project-records.js, with POET falling
// back to data/project-record-poet.js). Those files are regenerated by the sync
// pipeline, so a user CANNOT edit them in place. This endpoint is the SEPARATE
// override store: a user with office access can manually enter/edit any field in
// any section and that value is stored here in KV, MERGED on top of the synced
// record at render time (the override ALWAYS wins). Overrides survive reload and
// survive a future data sync, and are visible to the whole office.
//
// WHAT IT STORES
//   project_override_v1:<num>  ->  JSON {
//     num,                                  // the project number this belongs to
//     sections: { <sectionKey>: { <fieldLabel>: <stringValue>, ... }, ... },
//     _meta: { updatedBy, updatedAt }       // last writer + when (server-set)
//   }
//   sectionKey is one of the 11 stable card keys (general, pfTeam, contract,
//   engineering, safety, siteReadiness, equipment, material, qaqc, financials,
//   closeout). fieldLabel is the field's display label (the same label the
//   renderer shows). Values are STRINGS (text/number/date all stored as text;
//   the client formats). ZERO financial computation happens here -- this is a
//   plain string overlay keyed by (section, label). Money strings a user types
//   are stored verbatim as text; nothing is summed, priced, or derived.
//
// KV KEY: env.PF_SCHEDULE :: 'project_override_v1:<num>'  (one key per project).
//
// RBAC (the critical part):
//   - Behind the auth gate (functions/_middleware.js): no session -> 401.
//   - FINANCIALS area (the office): requireArea(session, 'financials') on GET and
//     POST. financials = admin/partner/business_dev -- the SAME roles that can
//     view/edit the project record. field_ops is BLOCKED (can neither read nor
//     write overrides), even by direct URL. /api/project-override -> 'financials'
//     in areaForPath (defense-in-depth with this handler's requireArea).
//   - WRITE hardening (mirrors daily-report/pm-project): body cap, strict JSON ->
//     400, section validated against the fixed key list, fields rebuilt +
//     length-capped, angle brackets stripped, updatedBy/updatedAt set from the
//     SESSION (never client-supplied), no eval. Private no-store.
//   - FAIL CLOSED: if KV is not bound, POST returns 503 (the client keeps the
//     user in edit mode and shows an honest error -- it NEVER shows "saved").
//   - NO mail, NO outbound fetch.

import { requireArea } from '../lib/auth.js';

const KV_PREFIX = 'project_override_v1:';
const MAX_BODY_BYTES = 64 * 1024;   // an override for one section (many fields) fits easily
const MAX_LABEL = 200;              // a field label
const MAX_VALUE = 4000;             // a manually entered value (text/number/date)
const MAX_FIELDS_PER_SECTION = 200; // generous cap; a section has ~25 fields
const MAX_TOTAL_SECTIONS = 40;      // > the 11 cards, room to grow; bounds abuse

// The stable section keys the renderer uses for its 11 cards. A POST for any
// other section key is rejected (400) so the store can never accumulate junk
// keys. Mirrors the SECTION_LABELS map / card list in the client renderer.
const VALID_SECTIONS = {
  general: 1, pfTeam: 1, contract: 1, engineering: 1, safety: 1,
  siteReadiness: 1, equipment: 1, material: 1, qaqc: 1,
  financials: 1, closeout: 1,
  // design_professionals (Brad 2026-08-07): the General Info "Design Professionals"
  // block (the 4 engineering-firm contact cards: Ground Improvement / Geotechnical /
  // Civil / Structural) is now its OWN editable nested card. It gets its own override
  // key so its firm/contact edits persist per-project WITHOUT colliding with the
  // standalone Engineering & Design section's `engineering` key (which owns that
  // section's tracking fields). Same RBAC (financials area; field_ops blocked), same
  // string-overlay semantics as every other key here.
  design_professionals: 1,
};

const JSON_HEADERS = {
  'Content-Type': 'application/json',
  'Cache-Control': 'private, no-store',
};

function json(body, status = 200) {
  return new Response(JSON.stringify(body), { status, headers: JSON_HEADERS });
}

// A project number: "YY-NNN" style, but we accept any short slug of
// digits/letters/hyphens so helical (25-2001) and any future scheme work. The
// number is part of the KV key, so it MUST be tightly constrained.
function cleanNum(v) {
  const str = String(v == null ? '' : v).trim();
  if (!/^[A-Za-z0-9-]{1,20}$/.test(str)) return '';
  return str;
}

function s(v, cap) {
  if (v == null) return '';
  let str = String(v);
  if (str.length > cap) str = str.slice(0, cap);
  return str.replace(/[<>]/g, ''); // strip angle brackets (UI also escapes)
}

function kvKey(num) { return KV_PREFIX + num; }

// Load the stored override object for one project, or an empty shell.
async function loadOverride(env, num) {
  const raw = await env.PF_SCHEDULE.get(kvKey(num));
  if (!raw) return { num, sections: {}, _meta: { updatedBy: null, updatedAt: null } };
  try {
    const p = JSON.parse(raw);
    const sections = (p && p.sections && typeof p.sections === 'object') ? p.sections : {};
    const _meta = (p && p._meta && typeof p._meta === 'object')
      ? p._meta : { updatedBy: null, updatedAt: null };
    return { num, sections, _meta };
  } catch {
    // Corrupt value -> treat as empty (never fabricate). A fresh save overwrites it.
    return { num, sections: {}, _meta: { updatedBy: null, updatedAt: null } };
  }
}

// Rebuild a clean field map { label: value } from arbitrary client input. Only
// string labels -> string values survive; everything is length-capped and
// angle-bracket stripped. Empty-string values are KEPT (an empty string is a
// legitimate manual override meaning "blank this field").
function cleanFields(input) {
  const out = {};
  if (!input || typeof input !== 'object') return out;
  const keys = Object.keys(input).slice(0, MAX_FIELDS_PER_SECTION);
  for (const k of keys) {
    const label = s(k, MAX_LABEL);
    if (!label) continue;
    out[label] = s(input[k], MAX_VALUE);
  }
  return out;
}

// ---- GET: return the stored override object for ?num=<project_number> -------
export async function onRequestGet(context) {
  const { request, env } = context;
  const denied = requireArea(context.data && context.data.session, 'financials');
  if (denied) return denied;
  try {
    const url = new URL(request.url);
    const num = cleanNum(url.searchParams.get('num'));
    if (!num) return json({ status: 'error', message: 'A valid project number is required.' }, 400);

    if (!env.PF_SCHEDULE) {
      // No KV binding: no overrides exist. This is a benign empty read (a project
      // simply has no manual overrides), so return an empty object, not an error.
      return json({ ok: true, num, sections: {}, _meta: { updatedBy: null, updatedAt: null }, fallback: true });
    }
    const rec = await loadOverride(env, num);
    return json({ ok: true, num, sections: rec.sections, _meta: rec._meta });
  } catch (err) {
    console.error('api/project-override GET error:', err);
    return json({ status: 'error', message: 'An internal error occurred.' }, 500);
  }
}

// ---- POST: merge/save one section's field overrides -------------------------
//   body: { num, section, fields:{ label:value, ... } }
// Merges `fields` into sections[section] (per-field merge: a field the client
// omits is LEFT as-is; a field set to '' is stored as a blank override). Stamps
// updatedBy (session) + updatedAt. Returns the FULL saved override object so the
// client can re-render from server truth.
export async function onRequestPost(context) {
  const { request, env } = context;
  const session = context.data && context.data.session;
  const denied = requireArea(session, 'financials');   // office only; field_ops blocked
  if (denied) return denied;
  try {
    const len = Number(request.headers.get('Content-Length') || '0');
    if (len > MAX_BODY_BYTES) return json({ status: 'error', message: 'Payload too large.' }, 413);
    const text = await request.text();
    if (text.length > MAX_BODY_BYTES) return json({ status: 'error', message: 'Payload too large.' }, 413);

    let parsed;
    try { parsed = JSON.parse(text); }
    catch { return json({ status: 'error', message: 'Invalid JSON.' }, 400); }

    const num = cleanNum(parsed && parsed.num);
    if (!num) return json({ status: 'error', message: 'A valid project number is required.' }, 400);

    const section = String((parsed && parsed.section) || '');
    if (!VALID_SECTIONS[section]) {
      return json({ status: 'error', message: 'Unknown section.' }, 400);
    }

    const fields = cleanFields(parsed && parsed.fields);

    // FAIL CLOSED: no KV -> we cannot persist. Do NOT report success.
    if (!env.PF_SCHEDULE) {
      return json({ status: 'error',
        message: 'Persistence unavailable: KV binding PF_SCHEDULE is not configured on this deployment. Your edit was NOT saved.' }, 503);
    }

    const rec = await loadOverride(env, num);

    // Per-field merge into the section (KV read-modify-write; single-writer
    // acceptable for a project record edited by one office user at a time -- same
    // known limitation as daily-report; a D1 migration is the durable fix).
    const existing = (rec.sections[section] && typeof rec.sections[section] === 'object')
      ? rec.sections[section] : {};
    const merged = Object.assign({}, existing, fields);
    rec.sections[section] = merged;

    // Bound the number of sections (defense against a crafted flood of junk keys;
    // VALID_SECTIONS already limits keys to the 11, so this can only trip on abuse).
    if (Object.keys(rec.sections).length > MAX_TOTAL_SECTIONS) {
      return json({ status: 'error', message: 'Too many sections.' }, 413);
    }

    const who = (session && (session.name || session.uid)) ? s(session.name || session.uid, MAX_LABEL) : 'unknown';
    const nowIso = new Date().toISOString();
    rec._meta = { updatedBy: who, updatedAt: nowIso };

    const toStore = { version: 1, num: rec.num, sections: rec.sections, _meta: rec._meta };
    await env.PF_SCHEDULE.put(kvKey(num), JSON.stringify(toStore));

    return json({ ok: true, saved: true, num, section, sections: rec.sections, _meta: rec._meta });
  } catch (err) {
    console.error('api/project-override POST error:', err);
    return json({ status: 'error', message: 'An internal error occurred.' }, 500);
  }
}
